// ---- Evaluating generative models: shared helpers (prefix ev) ----
// EV (20_js_ev_0data.js) is generated by runs/make_data.py from out/*.json; every number in the prose comes from EV.txt.
window.EVH=(function(){
  const E=window.EV;
  const SET=Object.fromEntries(E.sets.map(s=>[s.k,s]));
  const MET={fid:{name:'FID',unit:'',dp:1},kid:{name:'KID x 1,000',unit:'',dp:2},cmmd:{name:'CMMD',unit:'',dp:3},
    fd_dino:{name:'FD-DINOv2',unit:'',dp:0},fd_clf:{name:'FD (classifier)',unit:'',dp:1}};
  const mean=a=>a.reduce((x,y)=>x+y,0)/a.length;
  function fmt(v,dp){if(v==null||!isFinite(v))return 'n/a';const a=Math.abs(v);
    if(dp==null)dp=a>=100?0:a>=10?1:a>=1?2:3;return v.toLocaleString('en-US',{minimumFractionDigits:dp,maximumFractionDigits:dp})}
  // value of metric m for set k at N (mean over draws) and its min/max
  function val(k,m,n){const i=E.ns.indexOf(n);const d=E.m[k][m][i];return {mean:mean(d),min:Math.min(...d),max:Math.max(...d),draws:d}}
  // fill every [data-ev] span from EV.txt
  function fill(root){(root||document).querySelectorAll('[data-ev]').forEach(el=>{const k=el.dataset.ev;
    if(k in E.txt)el.innerHTML=E.txt[k];else{el.textContent='?';if(window.__jsErr)window.__jsErr('missing text key '+k)}})}
  // grey uint8 image (base64 of w*h bytes) drawn into a canvas at integer scale
  function grey(cv,b64,w,h,scale){const raw=atob(b64);cv.width=w*scale;cv.height=h*scale;const ctx=cv.getContext('2d');
    const id=ctx.createImageData(w,h);for(let i=0;i<w*h;i++){const v=raw.charCodeAt(i);id.data[4*i]=id.data[4*i+1]=id.data[4*i+2]=v;id.data[4*i+3]=255}
    const t=document.createElement('canvas');t.width=w;t.height=h;t.getContext('2d').putImageData(id,0,0);
    ctx.imageSmoothingEnabled=false;ctx.drawImage(t,0,0,w*scale,h*scale)}
  // a strip of n grey 28x28 images stored side by side (base64 of 28 x 28n bytes, row-major over the strip)
  function strip(cv,b64,n,scale){grey(cv,b64,28*n,28,scale||2)}
  const col=k=>SET[k]?SET[k].color:'var(--mute)';
  // log-scale helpers
  const lg=Math.log10;
  function ticks(lo,hi){const out=[];for(let e=Math.floor(lg(lo));e<=Math.ceil(lg(hi));e++)[1,2,5].forEach(m=>{const v=m*Math.pow(10,e);if(v>=lo*0.999&&v<=hi*1.001)out.push(v)});return out}
  return {E,SET,MET,mean,fmt,val,fill,grey,strip,col,ticks,lg};
})();
EVH.fill();
